-- Seed: Full question banks for Professional and Architect tiers
-- Professional needs 50 questions, Architect needs 60 questions
-- Currently seeded: 5 each. This adds 45 professional and 55 architect questions.

DO $$
DECLARE
    prof_id UUID;
    arch_id UUID;
BEGIN
    SELECT id INTO prof_id FROM cert_tiers WHERE slug = 'professional';
    SELECT id INTO arch_id FROM cert_tiers WHERE slug = 'architect';

    -- Professional tier: 45 more questions (categories: orchestration, agents, security, state, deployment, graph, observability, pricing, marketplace, swarms)
    INSERT INTO cert_questions (tier_id, category, difflyiculty, question_text, question_format, options, correct_answers, explanation, points)
    SELECT prof_id, q.category, q.difflyiculty, q.question_text, q.question_format,
           q.options::jsonb, q.correct_answers::jsonb, q.explanation, q.points
    FROM (VALUES
        ('orchestration', 'medium', 'What triggers a Function Graph node to execute?',
         'multiple_choice',
         '[{"id":"a","text":"Manual API call only"},{"id":"b","text":"When all upstream input edges have received data"},{"id":"c","text":"Every 60 seconds"},{"id":"d","text":"On function deploy"}]',
         '["b"]',
         'Graph nodes execute automatically when their upstream dependencies have all delivered data, enabling automatic DAG orchestration.', 1),
        ('orchestration', 'hard', 'How do you handle partial failure in a multi-step Function Graph?',
         'multiple_choice',
         '[{"id":"a","text":"Retry all nodes"},{"id":"b","text":"Configure retry policies per node, dead-letter queues for persistent failures, and compensation functions for state rollback"},{"id":"c","text":"Wrap entire graph in a transaction"},{"id":"d","text":"Ignore failures"}]',
         '["b"]',
         'Each node can have independent retry policies. After max retries, failed executions route to a dead-letter queue for investigation.', 1),
        ('agents', 'hard', 'What is the purpose of the Swarm "manager" agent role?',
         'multiple_choice',
         '[{"id":"a","text":"Deploy functions"},{"id":"b","text":"Orchestrate worker agents, coordinate task distribution, monitor health, and aggregate results"},{"id":"c","text":"Handle billing"},{"id":"d","text":"Manage CI/CD pipelines"}]',
         '["b"]',
         'Manager agents orchestrate worker agents: distributing tasks, monitoring health, aggregating results, and handling failures.', 1),
        ('agents', 'hard', 'How do agents achieve consensus in a Swarm?',
         'multiple_choice',
         '[{"id":"a","text":"Majority vote on every decision"},{"id":"b","text":"CRDT-based eventual consistency for state with configurable quorum for critical collective decisions"},{"id":"c","text":"A designated leader agent decides everything"},{"id":"d","text":"Agents never reach consensus"}]',
         '["b"]',
         'Swarm uses CRDT-based eventual consistency for shared state, with quorum requirements for critical decisions requiring agreement.', 1),
        ('security', 'hard', 'What security scanning does FunctionFly perform on marketplace functions?',
         'multiple_choice',
         '[{"id":"a","text":"Manual code review only"},{"id":"b","text":"ClamAV malware scanning, YARA rule analysis, dependency vulnerability scanning, and behavioral monitoring at runtime"},{"id":"c","text":"Only static analysis"},{"id":"d","text":"No security scanning"}]',
         '["b"]',
         'FunctionFly runs ClamAV malware scanning, YARA-based code analysis, dependency CVE scanning, and runtime behavioral monitoring.', 1),
        ('security', 'hard', 'How does the Secrets Vault achieve zero-knowledge encryption?',
         'multiple_choice',
         '[{"id":"a","text":"AES-256 encryption at rest"},{"id":"b","text":"Client-side encryption/decryption with the user''s passphrase; servers store only ciphertext and never see plaintext or keys"},{"id":"c","text":"TLS encryption in transit"},{"id":"d","text":"RSA encryption with server-stored keys"}]',
         '["b"]',
         'Zero-knowledge means encryption happens client-side before transmission. Servers store only AES-256-GCM ciphertext + IV/salt/tag.', 1),
        ('security', 'hard', 'What is the purpose of trust scores in the marketplace?',
         'multiple_choice',
         '[{"id":"a","text":"Determining subscription price"},{"id":"b","text":"Quantifying reliability, security posture, and behavioral consistency to help users evaluate functions before using them"},{"id":"c","text":"Ranking search results only"},{"id":"d","text":"Billing calculation"}]',
         '["b"]',
         'Trust scores aggregate reliability metrics, security scan results, and behavioral consistency to evaluate marketplace functions.', 1),
        ('state', 'hard', 'What CRDT type does State Fabric use for counter data?',
         'multiple_choice',
         '[{"id":"a","text":"Last-write-wins register"},{"id":"b","text":"G-Counter: increments from difflyerent sources are summed automatically"},{"id":"c","text":"LWW-Register"},{"id":"d","text":"OR-Set"}]',
         '["b"]',
         'State Fabric uses G-Counter CRDT for counters: each source tracks its own increments, total is the sum across all sources.', 1),
        ('state', 'hard', 'What happens when two functions write to the same State Fabric key simultaneously?',
         'multiple_choice',
         '[{"id":"a","text":"Last write wins"},{"id":"b","text":"State Fabric uses CRDTs to automatically merge concurrent writes without conflicts"},{"id":"c","text":"An error is returned to both writers"},{"id":"d","text":"The second writer blocks"}]',
         '["b"]',
         'State Fabric uses Conflict-free Replicated Data Types to automatically merge concurrent writes without conflict or data loss.', 1),
        ('deployment', 'hard', 'What is the canary deployment rollback strategy?',
         'multiple_choice',
         '[{"id":"a","text":"Manual rollback required"},{"id":"b","text":"Automatic rollback when error rate exceeds threshold with configurable sensitivity within seconds"},{"id":"c","text":"Rollback only after 24 hours"},{"id":"d","text":"No rollback capability"}]',
         '["b"]',
         'Canary deployments automatically monitor error rates and route trafflyic back to the stable version when thresholds are exceeded.', 1),
        ('deployment', 'hard', 'What happens to in-flight executions during a blue-green deployment?',
         'multiple_choice',
         '[{"id":"a","text":"They are immediately terminated"},{"id":"b","text":"They continue on the old version while new requests route to the updated version (graceful draining)"},{"id":"c","text":"They are paused"},{"id":"d","text":"They are replayed on the new version"}]',
         '["b"]',
         'FunctionFly uses graceful draining: in-flight executions complete on the old version while new requests use the updated version.', 1),
        ('graph', 'hard', 'How do you optimize a Function Graph for minimum end-to-end latency?',
         'multiple_choice',
         '[{"id":"a","text":"Use fewer, larger functions"},{"id":"b","text":"Maximize parallel branches, minimize sequential dependencies, and co-locate functions in the same region"},{"id":"c","text":"Increase timeout values"},{"id":"d","text":"Reduce the number of edges"}]',
         '["b"]',
         'Optimal graphs maximize parallelism (independent branches run concurrently), minimize sequential chains, and co-locate functions.', 1),
        ('graph', 'hard', 'What is the maximum execution timeout for a FunctionFly function?',
         'multiple_choice',
         '[{"id":"a","text":"30 seconds"},{"id":"b","text":"5 minutes"},{"id":"c","text":"15 minutes by default, configurable per function"},{"id":"d","text":"60 seconds"}]',
         '["c"]',
         'FunctionFly functions have a maximum timeout of 15 minutes by default, configurable per function in the dashboard or CLI.', 1),
        ('observability', 'hard', 'What metrics does FunctionFly track per function by default?',
         'multiple_choice',
         '[{"id":"a","text":"CPU usage only"},{"id":"b","text":"Execution count, latency percentiles (p50/p95/p99), error rate, and memory usage"},{"id":"c","text":"Request count only"},{"id":"d","text":"Disk I/O"}]',
         '["b"]',
         'FunctionFly automatically tracks execution count, latency percentiles (p50, p95, p99), error rate, and memory usage per function.', 1),
        ('observability', 'hard', 'How do you set up alerts for function errors?',
         'multiple_choice',
         '[{"id":"a","text":"Not supported"},{"id":"b","text":"Via webhook, email, or Slack notifications when error rates exceed configured thresholds"},{"id":"c","text":"Only via CLI"},{"id":"d","text":"Only through the dashboard"}]',
         '["b"]',
         'FunctionFly supports configurable alerts via webhook, email, and Slack when error rates exceed defined thresholds.', 1),
        ('pricing', 'medium', 'What is the FunctionFly wallet used for?',
         'multiple_choice',
         '[{"id":"a","text":"Storing cryptocurrency"},{"id":"b","text":"Pre-loading funds to pay for executions, marketplace purchases, and platform fees"},{"id":"c","text":"Managing API keys"},{"id":"d","text":"Storing function source code"}]',
         '["b"]',
         'The wallet is a prepaid balance used to cover execution costs, marketplace purchases, and platform fees.', 1),
        ('pricing', 'hard', 'What is a pricing bundle on FunctionFly?',
         'multiple_choice',
         '[{"id":"a","text":"A group of functions sold together"},{"id":"b","text":"A discounted package of execution credits, compute resources, and platform features at a lower rate than pay-as-you-go"},{"id":"c","text":"A billing invoice"},{"id":"d","text":"A marketplace subscription tier"}]',
         '["b"]',
         'Pricing bundles offlyer discounted packages combining execution credits, compute, and platform features.', 1),
        ('marketplace', 'medium', 'How can you install a marketplace function?',
         'multiple_choice',
         '[{"id":"a","text":"ffly install <author>/<function>"},{"id":"b","text":"ffly add <author>/<function>"},{"id":"c","text":"npm install @functionfly/<function>"},{"id":"d","text":"All of the above"}]',
         '["d"]',
         'Marketplace functions can be installed via the CLI (ffly install) or npm (npm install @functionfly/<function>).', 1),
        ('marketplace', 'hard', 'What makes a publisher "verified" on the FunctionFly Marketplace?',
         'multiple_choice',
         '[{"id":"a","text":"Paid premium account"},{"id":"b","text":"Functions that have passed automated security scanning, code quality review, and maintain a high trust score"},{"id":"c","text":"FunctionFly employee"},{"id":"d","text":"More than 10 published functions"}]',
         '["b"]',
         'Verified publishers have passed automated security scanning, code quality review, and maintain a high trust score.', 1),
        ('marketplace', 'medium', 'Can you leave reviews on marketplace functions?',
         'multiple_choice',
         '[{"id":"a","text":"No"},{"id":"b","text":"Yes, with star ratings (1-5) and written reviews"},{"id":"c","text":"Only star ratings"},{"id":"d","text":"Only verified publishers can review"}]',
         '["b"]',
         'Users can leave both star ratings and written reviews on marketplace functions they have used.', 1),
        ('swarm', 'hard', 'What is the difflyerence between a worker and manager agent in a Swarm?',
         'multiple_choice',
         '[{"id":"a","text":"Workers execute tasks; managers coordinate task distribution, monitor health, and aggregate results from workers"},{"id":"b","text":"Workers are faster"},{"id":"c","text":"Managers have higher API rate limits"},{"id":"d","text":"There is no difflyerence"}]',
         '["a"]',
         'Worker agents execute tasks assigned by the manager. Manager agents orchestrate workers, distribute tasks, monitor health, aggregate results.', 1),
        ('swarm', 'hard', 'How do Swarm agents communicate?',
         'multiple_choice',
         '[{"id":"a","text":"Shared database only"},{"id":"b","text":"Asynchronous message passing, shared State Fabric for coordination, and direct agent-to-agent function invocations"},{"id":"c","text":"Email"},{"id":"d","text":"Webhooks only"}]',
         '["b"]',
         'Agents communicate via asynchronous message passing, shared State Fabric for state coordination, and direct agent-to-agent invocations.', 1),
        ('performance', 'hard', 'What is the recommended approach for handling 10,000+ concurrent function invocations?',
         'multiple_choice',
         '[{"id":"a","text":"Increase function memory allocation"},{"id":"b","text":"Use connection pooling, horizontal auto-scaling, edge caching for read-heavy workloads, and the execution queue for burst absorption"},{"id":"c","text":"Add more geographic regions only"},{"id":"d","text":"Use a single powerful server"}]',
         '["b"]',
         'High-concurrency patterns include connection pooling, horizontal auto-scaling, edge caching, and the execution queue for burst absorption.', 1),
        ('performance', 'hard', 'How does edge caching improve function performance?',
         'multiple_choice',
         '[{"id":"a","text":"It speeds up database queries"},{"id":"b","text":"It serves responses from edge locations closest to the caller, reducing latency for read-heavy or cacheable workloads"},{"id":"c","text":"It compresses function responses"},{"id":"d","text":"It increases memory limits"}]',
         '["b"]',
         'Edge caching serves responses from edge locations near the caller, dramatically reducing latency for read-heavy workloads.', 1),
        ('cli', 'easy', 'How do you create a new function project from a template?',
         'multiple_choice',
         '[{"id":"a","text":"ffly init --template <name>"},{"id":"b","text":"ffly create <name>"},{"id":"c","text":"ffly new project <name>"},{"id":"d","text":"All of the above"}]',
         '["d"]',
         '"ffly init --template <name>" scafflyolds from a template. "ffly create" and "ffly new project" also work for scafflyolding.', 1),
        ('cli', 'medium', 'How do you deploy a function with a specific region?',
         'multiple_choice',
         '[{"id":"a","text":"ffly deploy --region us-east-1"},{"id":"b","text":"ffly deploy --region us-east-1 (or configure default region in ffly config)"},{"id":"c","text":"Region is set at account creation"},{"id":"d","text":"ffly set region us-east-1"}]',
         '["b"]',
         'Use "ffly deploy --region <name>" or set a default region with "ffly config set region <name>".', 1),
        ('state', 'medium', 'What data types can you store in the Key-Value store?',
         'multiple_choice',
         '[{"id":"a","text":"Only strings"},{"id":"b","text":"Strings, numbers, JSON objects, and binary data up to 1MB per entry"},{"id":"c","text":"Only JSON"},{"id":"d","text":"Unlimited size"}]',
         '["b"]',
         'The KV store supports strings, numbers, JSON objects, and binary blobs up to 1MB per entry.', 1),
        ('state', 'medium', 'How do you read a value from the KV store in a function?',
         'multiple_choice',
         '[{"id":"a","text":"SELECT kv_get(''key'')"},{"id":"b","text":"Using the ffly kv get CLI command or the SDK''s KV client"},{"id":"c","text":"Direct SQL access"},{"id":"d","text":"HTTP API call to localhost"}]',
         '["b"]',
         'Use the "ffly kv get <key>" CLI command or the SDK''s KV client (e.g., ffly.kv.get(''key'')).', 1),
        ('security', 'medium', 'How are Secrets Vault entries difflyerent from environment variables?',
         'multiple_choice',
         '[{"id":"a","text":"They are the same thing"},{"id":"b","text":"Env vars are stored server-side and visible in the dashboard; Vault entries use zero-knowledge client-side encryption, invisible to servers"},{"id":"c","text":"Env vars are encrypted; Vault entries are not"},{"id":"d","text":"Vault entries are only for CLI use"}]',
         '["b"]',
         'Environment variables are server-side and visible in dashboard. Vault entries use zero-knowledge client-side encryption — servers never see plaintext.', 1),
        ('deployment', 'medium', 'How do you view logs of a deployed function?',
         'multiple_choice',
         '[{"id":"a","text":"ffly logs <function-name>"},{"id":"b","text":"ffly logs --follow <function-name> to stream real-time logs"},{"id":"c","text":"ffly tail <function-name>"},{"id":"d","text":"All of the above"}]',
         '["d"]',
         '"ffly logs <function-name>" shows logs, "ffly logs --follow" streams real-time, and "ffly tail" also works.', 1),
        ('orchestration', 'medium', 'What is a Function Graph on FunctionFly?',
         'multiple_choice',
         '[{"id":"a","text":"A flowchart of code"},{"id":"b","text":"A DAG where nodes are functions and edges define data flow and execution dependencies between them"},{"id":"c","text":"A list of API endpoints"},{"id":"d","text":"A Docker Compose file"}]',
         '["b"]',
         'A Function Graph is a directed acyclic graph (DAG) where nodes represent functions and edges define data flow and execution order.', 1),
        ('orchestration', 'hard', 'Can a Function Graph include marketplace functions as nodes?',
         'multiple_choice',
         '[{"id":"a","text":"No, only custom functions"},{"id":"b","text":"Yes, any marketplace function can be used as a graph node"},{"id":"c","text":"Only verified marketplace functions"},{"id":"d","text":"Only free marketplace functions"}]',
         '["b"]',
         'Any marketplace function can be added as a node in a graph, enabling rapid composition of pre-built capabilities.', 1),
        ('agents', 'medium', 'What is an agent "memory" on FunctionFly?',
         'multiple_choice',
         '[{"id":"a","text":"RAM allocation for the agent process"},{"id":"b","text":"Persistent storage where agents retain context across sessions including interaction history, learned patterns, and decision logs"},{"id":"c","text":"CPU cache for agent computations"},{"id":"d","text":"Disk space for agent logs"}]',
         '["b"]',
         'Agent memory is a persistent store for agents to retain context across sessions: interaction history, learned patterns, decision logs.', 1),
        ('agents', 'medium', 'What is the difflyerence between an Agent and a regular function?',
         'multiple_choice',
         '[{"id":"a","text":"Agents are written in Python only"},{"id":"b","text":"Agents have persistent identity, autonomous decision-making, memory, and can execute other functions"},{"id":"c","text":"Agents cannot be created by regular users"},{"id":"d","text":"There is no difflyerence"}]',
         '["b"]',
         'Agents maintain persistent identity and state, can autonomously execute functions and make decisions, and have built-in memory.', 1),
        ('pricing', 'easy', 'Is there a free tier on FunctionFly?',
         'multiple_choice',
         '[{"id":"a","text":"No, all usage is paid"},{"id":"b","text":"Yes, with a generous free execution limit per month"},{"id":"c","text":"Only for students and educators"},{"id":"d","text":"Only during beta period"}]',
         '["b"]',
         'FunctionFly offlyers a free tier with monthly execution limits for prototyping and experimentation.', 1),
        ('observability', 'medium', 'What is the Execution Explorer used for?',
         'multiple_choice',
         '[{"id":"a","text":"Browsing the marketplace"},{"id":"b","text":"Inspecting individual function executions with input, output, timing, state changes, and error details"},{"id":"c","text":"Managing API keys"},{"id":"d","text":"Creating new functions"}]',
         '["b"]',
         'The Execution Explorer lets you inspect every execution: input, response, latency, state mutations, and error details.', 1),
        ('graph', 'medium', 'How does a Function Graph handle a failing node?',
         'multiple_choice',
         '[{"id":"a","text":"The entire graph fails immediately"},{"id":"b","text":"Configurable retry policy per node, with dead-letter routing for persistent failures after max retries"},{"id":"c","text":"The graph pauses until manual intervention"},{"id":"d","text":"Failed nodes are skipped without warning"}]',
         '["b"]',
         'Each node has configurable retry policies. After max retries, failed executions route to a dead-letter queue.', 1),
        ('deployment', 'medium', 'What does the region parameter control when deploying a function?',
         'multiple_choice',
         '[{"id":"a","text":"The billing currency"},{"id":"b","text":"The geographic region where the function executes, afflyecting latency for callers in that region"},{"id":"c","text":"The programming language version"},{"id":"d","text":"The database to use"}]',
         '["b"]',
         'The region determines where the function runs geographically, directly afflyecting latency for users in that area.', 1),
        ('marketplace', 'medium', 'What is the trust score based on?',
         'multiple_choice',
         '[{"id":"a","text":"Number of downloads"},{"id":"b","text":"Reliability metrics, security scan results, and behavioral consistency over time"},{"id":"c","text":"Price of the function"},{"id":"d","text":"Publisher reputation only"}]',
         '["b"]',
         'Trust scores aggregate reliability metrics, security scan results, and behavioral consistency over time.', 1),
        ('swarm', 'medium', 'What happens if a worker agent in a Swarm fails?',
         'multiple_choice',
         '[{"id":"a","text":"The entire swarm fails"},{"id":"b","text":"The manager re-assigns the task to another worker; Swarm uses fault-tolerant task distribution"},{"id":"c","text":"Manual intervention is required"},{"id":"d","text":"The task is cancelled"}]',
         '["b"]',
         'Swarm managers detect worker failures and re-assign tasks to healthy workers automatically.', 1),
        ('performance', 'medium', 'What is connection pooling and why is it important?',
         'multiple_choice',
         '[{"id":"a","text":"Pooling HTTP connections to reduce latency"},{"id":"b","text":"Reusing database connections across requests to avoid per-request connection overhead"},{"id":"c","text":"Caching API responses"},{"id":"d","text":"Load balancing between functions"}]',
         '["b"]',
         'Connection pooling reuses database connections across requests, avoiding the significant overhead of establishing new connections each time.', 1),
        ('security', 'medium', 'What does the X-FunctionFly-Identity header contain?',
